/// Parse POSIX-style argv into Options.  args[0] is the program name
/// (skipped); `--` ends flag parsing; every matched flag sets its
/// field, coerced inline (the Dhall type never sees argv strings).
/// Accepted spellings: exact short/long tokens, argumentless short
/// clusters (-la == -l -a; a Value short never clusters) and inline
/// --long=value for Value longs.  Text operands are gpa-owned
/// dupes on success; on error earlier dupes are not freed (same
/// discipline as the hand parsers this replaces).
pub fn parsePosix(args: []const []const u8, gpa: Allocator) ParseError!Options {
    var strings_items = std.ArrayList([]const u8).empty;
    errdefer strings_items.deinit(gpa);
    var next_pos: usize = 0; // next single-positional slot to fill
    var o = Options{};
    var i: usize = 1;
    var after_ddash = false;
    while (i < args.len) : (i += 1) {
        const a = args[i];
        if (after_ddash) {
            try bindOperand(a, &o, &next_pos, gpa, &strings_items);
            continue;
        }
        if (std.mem.eql(u8, a, "--")) {
            after_ddash = true;
            continue;
        }
        var matched = false;
        if (a.len > 2 and a[0] == '-' and a[1] != '-') {
            var cluster = true;
            for (a[1..]) |ch| {
                var letter_matched = false;
                if (ch == 'n') {
                    o.no_newline = true;
                    letter_matched = true;
                }
                if (ch == 'e') {
                    o.escapes = true;
                    letter_matched = true;
                }
                if (!letter_matched) cluster = false;
            }
            if (cluster) continue;
        }
        if (!matched and (std.mem.eql(u8, a, "-n"))) {
            o.no_newline = true;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-e"))) {
            o.escapes = true;
            matched = true;
        }
        if (!matched) {
            if (a.len > 1 and a[0] == '-') {
                std.debug.print("fx-echo: unknown option '{s}'\n", .{ a });
                return error.UnknownOption;
            }
            try bindOperand(a, &o, &next_pos, gpa, &strings_items);
        }
    }
    if (strings_items.items.len > 0) o.strings = strings_items.toOwnedSlice(gpa) catch return error.OutOfMemory;
    return o;
}

fn bindOperand(arg: []const u8, o: *Options, next_pos: *usize, gpa: Allocator, strings_items: *std.ArrayList([]const u8)) ParseError!void {
    _ = o;
    _ = next_pos;
    strings_items.append(gpa, gpa.dupe(u8, arg) catch return error.OutOfMemory) catch return error.OutOfMemory;
}

